+  let bytes = FixedArray::make(length, b'\x00')
+  let read = file.read_at(bytes, position=size - length.to_int64())
+  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
+  let lines = text.split("\n").to_array()
+  let kept = FixedArray::make(lines.length(), false)
+  let mut remaining = 65536
+  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
+    if i == 0 && size > length.to_int64() {
+      continue
+    }
+    let length = lines[i].length() + 1
+    if length <= remaining {
+      kept[i] = true
+      remaining -= length
+    }
+  }
+  remaining = 65536
+  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
+    if kept[i] || (i == 0 && size > length.to_int64()) {
