+///|
+fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
+  let chars = text.iter().to_array()
+  let mut boundary = chars.length()
+  for secret in secrets {
+    let value = secret.iter().to_array()
+    if value.length() == 0 || text.has_suffix(secret) {
+      continue
+    }
+    let limit = if value.length() - 1 < boundary {
+      value.length() - 1
+    } else {
+      boundary
+    }
+    if limit == 0 {
+      continue
+    }
+    let prefixes = FixedArray::make(limit, 0)
+    let mut matched = 0
+    for index in 1..<limit {
+      while matched > 0 && value[matched] != value[index] {
+        matched = prefixes[matched - 1]
+      }
+      if value[matched] == value[index] {
+        matched += 1
+      }
+      prefixes[index] = matched
+    }
+    matched = 0
+    for index in 0..<boundary {
+      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
+        matched = prefixes[matched - 1]
+      }
+      if matched < limit && value[matched] == chars[index] {
+        matched += 1
+      }
+    }
+    boundary -= matched
+  }
+  if boundary == chars.length() {
+    text
+  } else {
+    character_text(chars, 0, boundary) + "[redacted]"
+  }
+}
