   132	  let kept = FixedArray::make(lines.length(), false)
   133	  let mut remaining = 65536
   134	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   135	    if i == 0 && size > length.to_int64() {
   136	      continue
   137	    }
   138	    let length = lines[i].length() + 1
   139	    if length <= remaining {
   140	      kept[i] = true
   141	      remaining -= length
   142	    }
   143	  }
   144	  remaining = 65536
   145	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   146	    if kept[i] || (i == 0 && size > length.to_int64()) {
   147	      continue
   148	    }
   149	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
