482	  protected_secrets? : Array[String],
483	  incomplete_final_line~ : Bool = false,
484	) -> String {
485	  let progress = Progress::new("diagnostic-error", environment?)
486	  if protected_values is Some(values) {
487	    for value in values {
488	      if value != "" {
489	        if value.length() < 4 {
490	          progress.short_values.push(value)
491	        } else {
492	          progress.secrets.push(value)
493	        }
494	      }
495	    }
496	  }
497	  if protected_secrets is Some(values) {
498	    for value in values {
499	      if value != "" {
500	        progress.secrets.push(value)
501	      }
502	    }
503	  }
504	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
505	  let lines = []
506	  let mut incomplete = omitted
507	  let source_lines = message.split("\n").to_array()
508	  for index in 0..<source_lines.length() {
509	    let line = source_lines[index]
510	    if lines.length() == 8 {
511	      incomplete = true
512	      ignore(lines.remove(1))
513	    }
514	    let truncated = line.length() > 1024
515	    let bounded = if truncated {
516	      incomplete = true
517	      line[:1024].to_owned()
518	    } else {
519	      line.to_owned()
520	    }
521	    let bounded = if truncated ||
522	      (incomplete_final_line && index == source_lines.length() - 1) {
523	      diagnostic_partial_secret(
524	        bounded,
525	        progress.secrets + progress.short_values,
526	      )
527	    } else {
528	      bounded
529	    }
530	    match progress.safe_message(bounded) {
531	      Some(safe) => lines.push(safe)
532	      None => {
533	        incomplete = true
534	        lines.push("[unavailable]")
535	      }
536	    }
537	  }
538	  if (incomplete || progress.details_truncated) &&
539	    lines.last() != Some("[error details incomplete or truncated]") {
540	    lines.push("[error details incomplete or truncated]")
541	  }
542	  lines.join("\n")
543	}
