545	///|
546	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
547	  let chars = text.iter().to_array()
548	  let mut boundary = chars.length()
549	  for secret in secrets {
550	    let value = secret.iter().to_array()
551	    if value.length() == 0 || text.has_suffix(secret) {
552	      continue
553	    }
554	    let limit = if value.length() - 1 < boundary {
555	      value.length() - 1
556	    } else {
557	      boundary
558	    }
559	    if limit == 0 {
560	      continue
561	    }
562	    let prefixes = FixedArray::make(limit, 0)
563	    let mut matched = 0
564	    for index in 1..<limit {
565	      while matched > 0 && value[matched] != value[index] {
566	        matched = prefixes[matched - 1]
567	      }
568	      if value[matched] == value[index] {
569	        matched += 1
570	      }
571	      prefixes[index] = matched
572	    }
573	    matched = 0
574	    for index in 0..<boundary {
575	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
576	        matched = prefixes[matched - 1]
577	      }
578	      if matched < limit && value[matched] == chars[index] {
579	        matched += 1
580	      }
581	    }
582	    boundary -= matched
583	  }
584	  if boundary == chars.length() {
585	    text
586	  } else {
587	    character_text(chars, 0, boundary) + "[redacted]"
588	  }
589	}
