591	///|
592	priv struct DiagnosticProtectedValues {
593	  values : Array[String]
594	  secrets : Array[String]
595	  mut visited : Int32
596	  mut incomplete : Bool
597	}
598	
599	///|
600	fn diagnostic_protected_values(
601	  value : Json,
602	  result : DiagnosticProtectedValues,
603	  secret~ : Bool = false,
604	) -> Unit {
605	  if result.visited >= 4096 ||
606	    result.values.length() + result.secrets.length() >= 512 {
607	    result.incomplete = true
608	    return
609	  }
610	  result.visited += 1
611	  match value {
612	    Json::String(text) if text != "" => {
613	      let destination = if secret { result.secrets } else { result.values }
614	      destination.push(text)
615	      for line in text.split("\n") {
616	        if line != "" && line.length() < text.length() {
617	          if result.values.length() + result.secrets.length() >= 512 {
618	            result.incomplete = true
619	            return
620	          }
621	          destination.push(line.to_owned())
622	        }
623	        for word in line.split(" ") {
624	          for part in word.split("=") {
625	            if part == "" || part.length() >= text.length() {
626	              continue
627	            }
628	            if result.values.length() + result.secrets.length() >= 512 {
629	              result.incomplete = true
630	              return
631	            }
632	            destination.push(part.to_owned())
633	          }
634	        }
635	      }
636	      let escaped = Json::string(text).stringify()
637	      if escaped.length() > 2 {
638	        let encoded = escaped[1:escaped.length() - 1].to_owned()
639	        if encoded != "" && encoded != text {
640	          if result.values.length() + result.secrets.length() >= 512 {
641	            result.incomplete = true
642	            return
643	          }
644	          destination.push(encoded)
645	        }
646	      }
647	    }
648	    Json::Array(values) =>
649	      for item in values {
650	        diagnostic_protected_values(item, result, secret~)
651	      }
652	    Json::Object(values) =>
653	      for name, item in values {
654	        let key = name.to_lower().replace_all(old="_", new="")
655	        diagnostic_protected_values(
656	          item,
657	          result,
658	          secret=secret || credential_field(name) || key == "pairingcode",
659	        )
660	      }
661	    _ => ()
662	  }
663	}
