665	///|
666	fn diagnostic_output(
667	  output : Bytes,
668	  environment : Map[String, String],
669	  protected_input? : String,
670	  omitted~ : Bool = false,
671	) -> String? {
672	  if output.length() == 0 {
673	    return None
674	  }
675	  let safeguards : DiagnosticProtectedValues = {
676	    values: [],
677	    secrets: [],
678	    visited: 0,
679	    incomplete: false,
680	  }
681	  if protected_input is Some(input) {
682	    diagnostic_protected_values(@json.parse(input), safeguards) catch {
683	      _ => safeguards.incomplete = true
684	    }
685	  }
686	  if safeguards.incomplete {
687	    return Some(
688	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
689	    )
690	  }
691	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
692	  let incomplete = omitted || limit < output.length()
693	  Some(
694	    diagnostic_text(
695	      @utf8.decode_lossy(output[:limit]),
696	      environment~,
697	      omitted=incomplete,
698	      protected_values=safeguards.values,
699	      protected_secrets=safeguards.secrets,
700	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
701	    ),
702	  )
703	}
