705	///|
706	async fn diagnostic_capture(
707	  reader : @process.ReadFromProcess,
708	  limit : Int32,
709	) -> (Bytes, Bool) {
710	  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
711	  let mut truncated = false
712	  while reader.read_some(max_len=4096) is Some(chunk) {
713	    let remaining = limit - output.length()
714	    let count = if chunk.length() < remaining {
715	      chunk.length()
716	    } else {
717	      remaining
718	    }
719	    if count > 0 {
720	      output.write_bytes(chunk[:count])
721	    }
722	    if count < chunk.length() {
723	      truncated = true
724	    }
725	  }
726	  (output.to_bytes(), truncated)
727	}
