193	///|
194	async fn codex_rpc_response(
195	  reader : @process.ReadFromProcess,
196	  id : Int32,
197	  secrets : Array[String],
198	) -> Unit {
199	  let bytes : Array[Byte] = []
200	  let mut total = 0
201	  while true {
202	    let byte = reader.read_exactly(1)[0]
203	    total += 1
204	    guard total <= 1048576 else {
205	      raise AdapterError("Codex refresh output limit")
206	    }
207	    if byte == b'\n' {
208	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
209	      bytes.clear()
210	      if field(response, "id") == Some(Json::number(id.to_double())) {
211	        if field(response, "error") is Some(error) {
212	          let code = match field(error, "code") {
213	            Some(Json::Number(value, ..)) => " code " + value.to_string()
214	            _ => ""
215	          }
216	          let message = match field(error, "message") {
217	            Some(Json::String(value)) =>
218	              ": " + diagnostic_text(value, protected_secrets=secrets)
219	            _ => ""
220	          }
221	          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
222	        }
223	        guard field(response, "result") != None else {
224	          raise AdapterError("Codex refresh RPC \{id} returned no result")
225	        }
226	        return
227	      }
228	    } else {
229	      bytes.push(byte)
230	    }
231	  }
232	}
