234	///|
235	async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
236	  let (reader, output) = @process.read_from_process()
237	  defer reader.close()
238	  let (input, writer) = @process.write_to_process()
239	  defer writer.close()
240	  let (errors, stderr) = @process.read_from_process()
241	  defer errors.close()
242	  let captured = @buffer.Buffer(size_hint=1024)
243	  let incomplete : Ref[Bool] = { val: false, }
244	  let finished : Ref[Bool] = { val: false, }
245	  let failure = try {
246	    @async.with_task_group(async fn(group) {
247	      ignore(
248	        @process.spawn(
249	          group,
250	          "codex",
251	          ["app-server", "--stdio"],
252	          extra_env={ "CODEX_HOME": home },
253	          stdin=input,
254	          stdout=output,
255	          stderr~,
256	          no_wait=true,
257	        ),
258	      )
259	      group.spawn_bg(no_wait=true, async fn() {
260	        while errors.read_some(max_len=4096) is Some(chunk) {
261	          let remaining = 8192 - captured.length()
262	          let count = if chunk.length() < remaining {
263	            chunk.length()
264	          } else {
265	            remaining
266	          }
267	          if count > 0 {
268	            captured.write_bytes(chunk[:count])
269	          }
270	          if count < chunk.length() {
271	            incomplete.val = true
272	          }
273	        }
274	        finished.val = true
275	      })
276	      let initialize : Json = {
277	        "id": 1,
278	        "method": "initialize",
279	        "params": {
280	          "clientInfo": { "name": "orca-env-devsy", "version": version },
281	        },
282	      }
283	      writer.write(initialize.stringify() + "\n")
284	      codex_rpc_response(reader, 1, secrets)
285	      writer.write("{\"method\":\"initialized\"}\n")
286	      writer.write(
287	        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
288	      )
289	      codex_rpc_response(reader, 2, secrets)
290	    })
291	    None
292	  } catch {
293	    error => Some(error)
294	  }
295	  if failure is Some(error) {
296	    if @async.is_being_cancelled() {
297	      raise error
298	    }
299	    let protected_input : Json = { "access_token": secrets }
300	    let detail = diagnostic_output(
301	      captured.to_bytes(),
302	      @env.get_env_vars(),
303	      protected_input=protected_input.stringify(),
304	      omitted=incomplete.val || !finished.val,
305	    )
306	    raise AdapterError(
307	      diagnostic_error(error) +
308	      detail
309	      .map(value => "\nCodex app-server stderr: " + value)
310	      .unwrap_or(
311	        if finished.val {
312	          ""
313	        } else {
314	          "\n[Codex app-server stderr incomplete]"
315	        },
316	      ),
317	    )
318	  }
319	}
