321	///|
322	async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
323	  let initial = read_codex_auth(home)
324	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
325	    return initial
326	  }
327	  let lock = @fs.open(
328	    home + "/.orca-env-devsy-refresh.lock",
329	    mode=ReadWrite,
330	    create_mode=OpenOrCreate,
331	    permission=0o600,
332	  )
333	  defer lock.close()
334	  while !lock.try_lock(Exclusive) {
335	    @async.sleep(100)
336	  }
337	  let before = read_codex_auth(home)
338	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
339	    return before
340	  }
341	  let mut phase = "refresh"
342	  try {
343	    refresh_codex(home, before.secrets)
344	    phase = "verify"
345	    let after = read_codex_auth(home)
346	    guard after.access != before.access && after.expiry > before.expiry else {
347	      raise AdapterError("Codex refresh not persisted")
348	    }
349	    save_diagnostic("codex-refresh", "success", recording~)
350	  } catch {
351	    error => {
352	      progress_write(
353	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
354	      )
355	      let detail = diagnostic_error(error)
356	      save_diagnostic(
357	        "codex-refresh",
358	        "warning",
359	        phase~,
360	        error_type=if error is @async.TimeoutError {
361	          "timeout"
362	        } else {
363	          "refresh_failed"
364	        },
365	        error_message=detail,
366	        recording~,
367	      )
368	    }
369	  }
370	  let current = read_codex_auth(home)
371	  guard current.expiry > @env.now().to_double() / 1000 else {
372	    raise AdapterError("Expired access token")
373	  }
374	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
375	    progress_write(
376	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
377	    )
378	  }
379	  current
380	}

  1	///|
  2	fn credential_field(name : String) -> Bool {
  3	  let name = name
  4	    .trim_start(chars="-")
  5	    .to_owned()
  6	    .to_lower()
  7	    .replace_all(old="-", new="_")
  8	  [
  9	    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
 10	    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
 11	    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
 12	    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
 13	    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
 14	    "x_amz_security_token", "x_goog_signature",
 15	  ].contains(name) ||
 16	  [
 17	    "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
 18	  ]
 19	  .iter()
 20	  .any(suffix => name.has_suffix(suffix))
 21	}
