119	
120	///|
121	fn sensitive_name(name : String) -> Bool {
122	  let name = name.to_lower()
123	  [
124	    "password", "passwd", "token", "secret", "api_key", "apikey", "auth", "credential",
125	    "private_key", "access_key", "cookie", "fnox_age_key",
126	  ]
127	  .iter()
128	  .any(marker => name.contains(marker))
129	}
130	
131	///|
132	fn Progress::new(
133	  stage : String,
134	  environment? : Map[String, String],
135	  recording_override? : Bool,
136	) -> Progress {
137	  let secrets = []
138	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
139	    if sensitive_name(name) && value != "" {
140	      secrets.push(value)
141	      // Multiline credentials must also be masked in line-oriented output.
142	      for part in value.split("\n") {
143	        if part.trim() != "" {
144	          secrets.push(part.to_owned())
145	        }
146	      }
147	    }
148	  }
149	  secrets.sort_by((a, b) => b.length().compare(a.length()))
150	  {
151	    stage,
152	    operations: {},
153	    builds: {},
154	    secrets,
155	    short_values: [],
156	    recording: recording_override.unwrap_or(
157	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
158	      Some("0"),
159	    ),
160	    phase_count: 0,
161	    private_key: false,
162	    classic_build: false,
163	    recent: [],
164	    failures: [],
165	    details_truncated: false,
166	  }
167	}
168	
169	///|
170	fn terminal_text(text : String) -> String? {
171	  let output = @buffer.Buffer(size_hint=256)
172	  let mut state = 0
173	  for c in text.iter() {
174	    match state {
175	      0 =>
176	        if c == '\u001b' {
177	          state = 1
178	        } else if c.to_int() < 32 && c != '\t' {
179	          return None
180	        } else {
181	          output.write_char_utf8(c)
182	        }
183	      1 =>
184	        if c == '[' {
185	          state = 2
186	        } else if c == ']' {
187	          state = 3
188	        } else {
189	          return None
190	        }
191	      2 => if c >= '@' && c <= '~' { state = 0 }
192	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
193	      _ => if c == '\\' { state = 0 } else { state = 3 }
194	    }
195	  }
196	  if state != 0 {
197	    None
198	  } else {
199	    Some(@utf8.decode_lossy(output.to_bytes()))
200	  }
201	}
202	
203	///|
204	fn Progress::remember(
205	  self : Progress,
206	  message : String,
207	  warning~ : Bool,
208	) -> Unit {
209	  let lines = if warning { self.failures } else { self.recent }
210	  if lines.last() == Some(message) {
211	    return
212	  }
213	  if lines.length() == 8 {
214	    ignore(lines.remove(0))
215	    self.details_truncated = true
216	  }
217	  lines.push(message)
218	}
219	
220	///|
221	fn Progress::failure_detail(self : Progress) -> String {
222	  let lines = self.failures +
223	    self.recent.filter(line => !self.failures.contains(line))
224	  let detail = if lines.is_empty() {
225	    "no readable error message from subprocess"
226	  } else {
227	    lines.join("\n")
228	  }
229	  detail +
