252	      recording=self.recording,
253	    )
254	  } else if self.phase_count == 128 {
255	    self.phase_count += 1
256	    save_diagnostic(
257	      self.stage,
258	      "diagnostics-truncated",
259	      error_type="phase_limit",
260	      recording=self.recording,
261	    )
262	  }
263	  let key = ["pipeline", "operationId", "phase", "step"]
264	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
265	    .join(":")
266	  if state == "started" {
267	    if self.operations.length() >= 256 {
268	      self.operations.clear()
269	    }
270	    self.operations.set(key, @env.now())
271	    progress_message(label + ": running…")
272	  } else {
273	    let duration = match field(event, "durationMs") {
274	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
275	        Some(seconds(value.to_uint64()))
276	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
277	    }
278	    self.operations.remove(key)
279	    let timing = duration.map(value => value + ", ").unwrap_or("") +
280	      "elapsed " +
281	      seconds(@env.now() - progress_started)
282	    progress_message(
283	      label +
284	      ": " +
285	      (if state == "succeeded" { "done" } else { state }) +
286	      " (" +
287	      timing +
288	      ")",
289	    )
290	  }
291	}
292	
293	///|
294	fn classic_build_step(text : String) -> Bool {
295	  guard text.has_prefix("Step ") &&
296	    text[5:].split_once("/") is Some((step, rest)) &&
297	    rest.split_once(" ") is Some((total, detail)) else {
298	    return false
299	  }
300	  step.length() > 0 &&
301	  total.length() > 0 &&
302	  step.iter().all(c => c >= '0' && c <= '9') &&
303	  total.iter().all(c => c >= '0' && c <= '9') &&
304	  detail.trim().has_prefix(":")
305	}
306	
307	///|
308	async fn Progress::message(
309	  self : Progress,
310	  text : String,
311	  debug~ : Bool,
312	  warning~ : Bool,
313	  emit~ : Bool = true,
314	) -> Unit {
315	  for line in text.split("\n") {
316	    let text = line.trim().to_owned()
317	    if text == "" {
318	      continue
319	    }
320	    guard self.safe_message(text) is Some(safe) else {
321	      self.details_truncated = true
322	      continue
323	    }
324	    if !debug || warning {
325	      self.remember(safe, warning~)
326	    }
327	    if !emit {
328	      continue
329	    }
330	    if safe.has_prefix("#") {
331	      guard safe.split_once(" ") is Some((id, rest)) &&
332	        id.length() > 1 &&
333	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
334	        continue
335	      }
336	      let detail = rest.trim().to_owned()
337	      guard detail.has_prefix("[") ||
338	        detail.has_prefix("DONE") ||
339	        detail.has_prefix("ERROR") ||
340	        detail.has_prefix("CACHED") else {
341	        continue
342	      }
343	      if detail.has_prefix("ERROR") && debug && !warning {
344	        self.remember(safe, warning=true)
345	      }
346	      if self.builds.get(id.to_owned()) == Some(detail) {
347	        continue
348	      }
349	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
350	        self.builds.set(id.to_owned(), detail)
351	      }
352	      progress_message("Build " + id.to_owned() + ": " + detail)
353	    } else if classic_build_step(safe) {
354	      // Classic RUN output has no prefix. Only its own completion marker
355	      // ends this mode; phase events on another pipe can arrive ahead of it.
356	      self.classic_build = true
357	      progress_message("Build " + safe)
358	    } else if safe.has_prefix("Successfully built ") ||
359	      safe.has_prefix("Successfully tagged ") {
360	      self.classic_build = false
361	      progress_message("Build: " + safe)
362	    } else if self.classic_build && !warning {
363	      continue
364	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
365	      progress_message(self.stage + ": " + safe)
366	    } else if !debug && safe.has_prefix("[credential") {
367	      progress_message(self.stage + ": " + safe)
368	    }
369	  }
370	}

