 41	///|
 42	priv struct IdleTimer {
 43	  mut elapsed : Int64
 44	  mut seen : Bool
 45	  mut previous : Int64?
 46	  mut epoch : Int64
 47	}
 48	
 49	///|
 50	fn IdleTimer::advance(
 51	  self : IdleTimer,
 52	  activity : String,
 53	  now : Int64,
 54	) -> Unit raise {
 55	  guard now >= 0 else { raise AdapterError("Idle clock unavailable") }
 56	  let delta = match self.previous {
 57	    Some(last) if now >= last => now - last
 58	    _ => 0L
 59	  }
 60	  if activity == "active" {
 61	    self.elapsed = 0
 62	    self.seen = false
 63	  } else if activity == "idle" || (activity == "unknown" && self.seen) {
 64	    if self.seen {
 65	      self.elapsed = if self.elapsed + delta > 9007199254740991L {
 66	        9007199254740991L
 67	      } else {
 68	        self.elapsed + delta
 69	      }
 70	    }
 71	    self.seen = true
 72	  }
 73	  self.previous = Some(now)
 74	}
