 32	  match field(state, "idleTimeoutMs") {
 33	    None => None
 34	    Some(Json::Number(n, ..)) if n > 0 &&
 35	      n <= 9007199254740991.0 &&
 36	      n == n.to_int64().to_double() => Some(n.to_int64())
 37	    _ => raise AdapterError("Invalid saved idle timeout")
 38	  }
