373	async fn Progress::line(
374	  self : Progress,
375	  line : String,
376	  statuses~ : Bool,
377	  messages~ : Bool,
378	) -> Unit {
379	  if line.trim() == "" {
380	    return
381	  }
382	  let event = @json.parse(line) catch { _ => Json::null() }
383	  if field(event, "kind") == Some(Json::string("status")) {
384	    if field(event, "state") == Some(Json::string("failed")) &&
385	      field(event, "error") is Some(error) {
386	      for name in ["message", "hint"] {
387	        if field(error, name) is Some(Json::String(text)) {
388	          self.message(
389	            text,
390	            debug=false,
391	            warning=true,
392	            emit=messages || statuses,
393	          )
394	        }
395	      }
396	    }
397	    if statuses || messages {
398	      self.status(event)
399	    }
400	    return
401	  }
402	  // Result envelopes and arbitrary structured responses are never log text.
403	  if field(event, "kind") == Some(Json::string("result")) {
404	    return
405	  }
406	  if event is Json::Object(_) {
407	    let kind = field(event, "kind")
408	    guard kind == None ||
409	      kind == Some(Json::string("log")) ||
410	      kind == Some(Json::string("error")) else {
411	      return
412	    }
413	    let message = match field(event, "msg") {
414	      Some(value) => Some(value)
415	      None => field(event, "message")
416	    }
417	    guard message is Some(Json::String(text)) else { return }
418	    let level = field(event, "level")
419	    self.message(
420	      text,
421	      debug=level == Some(Json::string("debug")) ||
422	        level == Some(Json::string("trace")),
423	      warning=kind == Some(Json::string("error")) ||
424	        level == Some(Json::string("warn")) ||
425	        level == Some(Json::string("error")),
426	      emit=messages || (statuses && kind != None),
427	    )
428	  } else {
429	    if event != Json::null() {
430	      return
431	    }
432	    // Malformed JSON and binary output are not a safe free-text fallback.
433	    let text = line.trim().to_owned()
434	    if text.has_prefix("{") || text.has_prefix("[") {
435	      self.details_truncated = true
436	      return
437	    }
438	    self.message(
439	      text,
440	      debug=text.contains(" DEBUG ") ||
441	        text.contains(" TRACE ") ||
442	        text.has_prefix("DEBUG ") ||
443	        text.has_prefix("TRACE "),
444	      warning=text.contains(" WARN ") ||
445	        text.contains(" ERROR ") ||
446	        text.has_prefix("WARN ") ||
447	        text.has_prefix("ERROR "),
448	      emit=messages,
449	    )
450	  }
451	}
