100	        while true {
101	          let count = output.read(bytes)
102	          if count == 0 {
103	            break
104	          }
105	          guard buffer.length() + count <= 4194304 else {
106	            raise AdapterError("Activity response too large")
107	          }
108	          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
109	        }
