287	  while @fs.exists(required(state, "tunnelDirectory") + "/enabled") &&
288	        @fs.exists(required(state, "tunnelDirectory") + "/idle-enabled") {
289	    retry_reason = "observer_reconnecting"
290	    let outcome = @async.with_task_group(async fn(group) {
291	      group.spawn_bg(no_wait=true, async fn() {
292	        while @fs.exists(required(state, "tunnelDirectory") + "/idle-enabled") {
293	          @async.sleep(100)
294	        }
295	        raise AdapterError("Idle monitoring disabled")
296	      })
297	      while true {
298	        let started = @async.now()
299	        let evidence = observe_activity(state)
300	        let activity = required(evidence, "activity")
301	        attempt = 0
302	        idle_tick(
303	          state,
304	          timer,
305	          activity,
