325	            raise AdapterError("Idle stop identity or running state changed")
326	          }
327	          let fresh = observe_activity(state)
328	          let current = required(fresh, "activity")
329	          idle_tick(
330	            state,
331	            timer,
332	            current,
333	            if current == "unknown" {
334	              "awaiting_idle_confirmation"
335	            } else {
336	              "monitoring"
337	            },
338	            @async.now(),
339	            observation=fresh,
340	          )
341	          if current == "idle" {
342	            busy.val = true
343	            defer {
344	              busy.val = false
345	            }

output.text:
